[CmdletBinding()]
param([Parameter(Mandatory)][string]$Simfile,[Parameter(Mandatory)][string]$Preview,[Parameter(Mandatory)][switch]$Approved,[int]$Width=1920,[int]$Height=1080)
$ErrorActionPreference='Stop';if(-not $Approved){throw 'Explicit -Approved is required after owner approval of the exact preview.'}
$inspect=& (Join-Path $PSScriptRoot 'Inspect-Background.ps1') -Simfile $Simfile;$source=(Resolve-Path -LiteralPath $Preview).Path;$target=$inspect.BackgroundPath;$beforeReference=$inspect.BackgroundReference;$stamp=Get-Date -Format 'yyyyMMdd-HHmmss';$backup="$target.pre-upscale-$stamp.bak";$temp=Join-Path (Split-Path -Parent $target) ('.background-install-'+[guid]::NewGuid().ToString('N')+$inspect.Extension)
Add-Type -AssemblyName System.Drawing;$input=[Drawing.Image]::FromFile($source)
try{$bitmap=New-Object Drawing.Bitmap $Width,$Height,([Drawing.Imaging.PixelFormat]::Format24bppRgb);try{$g=[Drawing.Graphics]::FromImage($bitmap);try{$g.Clear([Drawing.Color]::Black);$g.CompositingQuality=[Drawing.Drawing2D.CompositingQuality]::HighQuality;$g.InterpolationMode=[Drawing.Drawing2D.InterpolationMode]::HighQualityBicubic;$g.DrawImage($input,0,0,$Width,$Height);switch($inspect.Extension){'.png'{$bitmap.Save($temp,[Drawing.Imaging.ImageFormat]::Png)}'.bmp'{$bitmap.Save($temp,[Drawing.Imaging.ImageFormat]::Bmp)}default{$bitmap.Save($temp,[Drawing.Imaging.ImageFormat]::Jpeg)}}}finally{$g.Dispose()}}finally{$bitmap.Dispose()}}finally{$input.Dispose()}
try{Copy-Item -LiteralPath $target -Destination $backup;Move-Item -LiteralPath $temp -Destination $target -Force;$after=& (Join-Path $PSScriptRoot 'Inspect-Background.ps1') -Simfile $Simfile;if($after.Width-ne$Width-or$after.Height-ne$Height-or$after.FrameCount-ne 1){throw 'Installed background failed validation.'};if($after.BackgroundReference-cne$beforeReference){throw '#BACKGROUND reference changed unexpectedly.'};[pscustomobject]@{Installed=$target;Backup=$backup;Width=$after.Width;Height=$after.Height;Encoding=$after.Format;BackgroundReference=$after.BackgroundReference;RestartedITGmania=$false}}catch{if(Test-Path -LiteralPath $backup){Copy-Item -LiteralPath $backup -Destination $target -Force};throw}finally{if(Test-Path -LiteralPath $temp){Remove-Item -LiteralPath $temp -Force}}
